.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #f0f8ff;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #ffffff;
  --vt-accent: #d6a354;
  --vt-on-accent: #000000;
  --vt-accent-ink: #d6a354;
  --vt-accent-on-deep: #FDBB2D;
  --vt-line: #717275;

  min-height: 100vh;
  font-family: 'Manrope', sans-serif;
  line-height: 1.6;
  color: var(--vt-ink);
  background: var(--vt-surface);
}

.root :where(a) {
  color: inherit;
  text-decoration: none;
}

.root :where(button) {
  background: none;
  border: none;
}

.root :where(h1, h2, h3, h4, h5, h6) {
  font-family: 'Anton', sans-serif;
  font-weight: 700;
  margin: 0;
}

.root a:focus-visible,
.root button:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

.sidebar {
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  width: 300px;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  z-index: 100;
  display: flex;
  flex-direction: column;
  padding: 40px 20px;
}

.sidebarInner {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  flex: 1;
}

.logo {
  display: inline-block;
  margin-bottom: 50px;
}

.brand {
  font-size: 28px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.nav {
  display: flex;
  flex-direction: column;
  gap: 12px;
  text-align: center;
}

.nav a {
  color: var(--vt-on-accent);
  font-size: 16px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 8px 12px;
  transition: color 0.3s, background 0.3s;
  border-radius: 100px;
}

.nav a:hover,
.nav a:focus-visible {
  color: var(--vt-surface);
  background: var(--vt-surface-deep);
}

.main {
  margin-left: 300px;
}

.hero {
  position: relative;
  min-height: calc(100vh - 0px);
  display: flex;
  align-items: center;
  overflow: hidden;
  border-bottom: 10px solid var(--vt-accent);
}

.heroBg {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-size: cover;
  background-position: center;
}

.heroOverlay {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(135deg, var(--vt-accent) 0%, var(--vt-accent-on-deep) 100%);
  opacity: 0.55;
}

.heroContent {
  position: relative;
  z-index: 2;
  max-width: 650px;
  padding: 50px;
}

.heroTitle {
  font-size: 74px;
  color: var(--vt-surface);
  text-transform: uppercase;
  line-height: 1.1;
  margin-bottom: 10px;
}

.heroTitle em {
  font-style: italic;
  color: var(--vt-accent);
}

.heroText {
  font-size: 20px;
  font-weight: 300;
  color: var(--vt-surface);
  margin-bottom: 0;
}

.heroButtons {
  display: flex;
  gap: 10px;
  margin-top: 30px;
  flex-wrap: wrap;
}

.btnAccent,
.btnOutline {
  display: inline-block;
  padding: 12px 25px;
  border-radius: 100px;
  font-size: 14px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  transition: all 0.3s;
}

.btnAccent {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border: 2px solid var(--vt-accent);
}

.btnAccent:hover {
  background: var(--vt-accent-on-deep);
  border-color: var(--vt-accent-on-deep);
}

.btnOutline {
  background: transparent;
  color: var(--vt-surface);
  border: 2px solid var(--vt-surface);
}

.btnOutline:hover {
  background: var(--vt-surface);
  color: var(--vt-ink);
}

.heroBadge {
  position: absolute;
  right: 40px;
  bottom: 40px;
  width: 180px;
  height: 180px;
  border-radius: 50%;
  border: 10px solid var(--vt-accent);
  background: var(--vt-surface);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  text-decoration: none;
  color: var(--vt-ink);
  z-index: 2;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
}

.heroBadge img {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.25;
}

.heroBadge span {
  position: relative;
  z-index: 1;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  padding: 10px;
}

.section {
  padding: 100px 50px;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
}

.sectionTitle {
  font-size: 46px;
  text-transform: uppercase;
  margin-bottom: 40px;
  color: var(--vt-ink);
}

.storyGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 50px;
  align-items: center;
}

.storyText p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  line-height: 1.8;
  margin-bottom: 15px;
}

.storyText p:last-child {
  margin-bottom: 0;
}

.storyImageWrap {
  background: var(--vt-accent);
  border-radius: 20px;
  padding: 20px;
  transform: rotate(3deg);
}

